   120    datum return_val;             /* To return the first key. */
   121
   122    /* Set the default return value for not finding a first entry. */
   123    return_val.dptr = NULL;
   124    return_val.dsize = 0;
   125
   126    GDBM_DEBUG (GDBM_DEBUG_READ, "%s: getting first key", dbf->name);
   127
   128    /* Return immediately if the database needs recovery */
   129    GDBM_ASSERT_CONSISTENCY (dbf, return_val);
