    25  static void
    26  compute_directory_size (blksize_t block_size,
    27                          int *ret_dir_size, int *ret_dir_bits)
    28  {
    29    /* Create the initial hash table directory.  */
    30    int dir_size = 8 * sizeof (off_t);
    31    int dir_bits = 3;
    32
    33    if (block_size > INT_MAX / 2)
    34      block_size = INT_MAX / 2;
    35    while (dir_size < block_size && dir_bits < GDBM_HASH_BITS - 3)
    36      {
    37        dir_size <<= 1;
    38        dir_bits++;
    39      }
    40
    41    *ret_dir_size = dir_size;
    42    *ret_dir_bits = dir_bits;
    43  }
    44
    45  static inline int
    46  bucket_element_count (size_t bucket_size)
    47  {
    48    return (bucket_size - sizeof (hash_bucket)) / sizeof (bucket_element) + 1;
    49  }
    50
    51  static void
    52  gdbm_header_avail (gdbm_file_header *hdr,
    53                     avail_block **avail_ptr, size_t *avail_size,
    54                     gdbm_ext_header **exhdr)
    55  {
    56    switch (hdr->header_magic)
    57      {
    58      case GDBM_OMAGIC:
    59      case GDBM_MAGIC:
    60        *exhdr = NULL;
    61        *avail_ptr = &((gdbm_file_standard_header*)hdr)->avail;
    62        *avail_size = (hdr->block_size -
    63                       offsetof (gdbm_file_standard_header, avail));
    64        break;
    65
    66      case GDBM_NUMSYNC_MAGIC:
    67        *exhdr = &((gdbm_file_extended_header*)hdr)->ext;
    68        *avail_ptr = &((gdbm_file_extended_header*)hdr)->avail;
    69        *avail_size = (hdr->block_size -
    70                       offsetof (gdbm_file_extended_header, avail));
    71        break;
    72      }
    73  }
    74
    75  static int
    76  validate_header_std (gdbm_file_header const *hdr, struct stat const *st)
    77  {
    78    int result = GDBM_NO_ERROR;
    79    int dir_size, dir_bits;
    80
    81    if (!(hdr->block_size > 0
    82          && hdr->block_size > sizeof (gdbm_file_header)
    83          && hdr->block_size - sizeof (gdbm_file_header) >=
    84          sizeof(avail_block)))
    85      {
    86        return GDBM_BLOCK_SIZE_ERROR;
    87      }
    88
    89    /* Technically speaking, the condition below should read
    90           hdr->next_block != st->st_size
    91       However, gdbm versions prior to commit 4e819c98 could leave
    92       hdr->next_block pointing beyond current end of file. To ensure
    93       backward compatibility with these versions, the condition has been
    94       slackened to this: */
    95    if (hdr->next_block < st->st_size)
    96      result = GDBM_NEED_RECOVERY;
    97
    98    /* Make sure dir and dir + dir_size fall within the file boundary */
    99    if (!(hdr->dir > 0
   100          && hdr->dir < st->st_size
   101          && hdr->dir_size > 0
   102          && hdr->dir + hdr->dir_size < st->st_size))
   103      return GDBM_BAD_HEADER;
   104
   105    compute_directory_size (hdr->block_size, &dir_size, &dir_bits);
   106    if (!(hdr->dir_size >= dir_size))
   107      return GDBM_BAD_HEADER;
   108    compute_directory_size (hdr->dir_size, &dir_size, &dir_bits);
   109    if (hdr->dir_bits != dir_bits)
   110      return GDBM_BAD_HEADER;
   111
   112    if (!(hdr->bucket_size > 0 && hdr->bucket_size > sizeof (hash_bucket)))
   113      return GDBM_BAD_HEADER;
   114
   115    if (hdr->bucket_elems != bucket_element_count (hdr->bucket_size))
   116      return GDBM_BAD_HEADER;
   117
   118    return result;
   119  }
   120
   121  static int
   122  validate_header_numsync (gdbm_file_header const *hdr, struct stat const *st)
   123  {
   124    int result = GDBM_NO_ERROR;
