   235  GDBM_FILE
   236  gdbm_fd_open (int fd, const char *file_name, int block_size,
   237                int flags, void (*fatal_func) (const char *))
   238  {
   239    GDBM_FILE dbf;                /* The record to return. */
   240    struct stat file_stat;        /* Space for the stat information. */
   241    off_t       file_pos;         /* Used with seeks. */
   242    int         index;            /* Used as a loop index. */
   243
   244    /* Initialize the gdbm_errno variable. */
   245    gdbm_set_errno (NULL, GDBM_NO_ERROR, FALSE);
   246
   247    /* Get the status of the file. */
   248    if (fstat (fd, &file_stat))
   249      {
   250        if (flags & GDBM_CLOERROR)
   251          SAVE_ERRNO (close (fd));
   252        GDBM_SET_ERRNO2 (NULL, GDBM_FILE_STAT_ERROR, FALSE, GDBM_DEBUG_OPEN);
   253        return NULL;
   254      }
   255
   256    /* Allocate new info structure. */
   257    dbf = calloc (1, sizeof (*dbf));
   258    if (dbf == NULL)
   259      {
   260        if (flags & GDBM_CLOERROR)
   261          SAVE_ERRNO (close (fd));
   262        GDBM_SET_ERRNO2 (NULL, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_OPEN);
   263        return NULL;
   264      }
   265
   266    dbf->desc = fd;
   267
   268    /* Initialize some fields for known values.  This is done so gdbm_close
   269       will work if called before allocating some structures. */
   270    dbf->dir  = NULL;
   271    dbf->bucket = NULL;
   272    dbf->header = NULL;
   273
   274    /* Initialize cache */
   275    dbf->cache_tree = _gdbm_cache_tree_alloc ();
   276    _gdbm_cache_init (dbf, DEFAULT_CACHESIZE);
   277
   278    dbf->file_size = -1;
   279
   280    dbf->memory_mapping = FALSE;
   281    dbf->mapped_size_max = SIZE_T_MAX;
   282    dbf->mapped_region = NULL;
   283    dbf->mapped_size = 0;
   284    dbf->mapped_pos = 0;
   285    dbf->mapped_off = 0;
   286
   287    /* Save name of file. */
   288    dbf->name = strdup (file_name);
   289    if (dbf->name == NULL)
   290      {
   291        if (flags & GDBM_CLOERROR)
   292          close (fd);
   293        _gdbm_cache_free (dbf);
   294        free (dbf);
   295        GDBM_SET_ERRNO2 (NULL, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_OPEN);
   296        return NULL;
   297      }
   298
   299    /* Initialize the fatal error routine. */
   300    dbf->fatal_err = fatal_func;
   301
   302    dbf->fast_write = TRUE;       /* Default to setting fast_write. */
   303    dbf->file_locking = TRUE;     /* Default to doing file locking. */
   304    dbf->central_free = FALSE;    /* Default to not using central_free. */
   305    dbf->coalesce_blocks = FALSE; /* Default to not coalesce blocks. */
   306
   307    dbf->need_recovery = FALSE;
   308    dbf->last_error = GDBM_NO_ERROR;
   309    dbf->last_syserror = 0;
   310    dbf->last_errstr = NULL;
   311
   312    _gdbmsync_init (dbf);
   313
   314    /* GDBM_FAST used to determine whether or not we set fast_write. */
   315    if (flags & GDBM_SYNC)
   316      {
   317        /* If GDBM_SYNC has been requested, don't do fast_write. */
   318        dbf->fast_write = FALSE;
   319      }
   320    if (flags & GDBM_NOLOCK)
   320    if (flags & GDBM_NOLOCK)
   321      {
   322        dbf->file_locking = FALSE;
   323      }
   324
   325    dbf->cloexec = !!(flags & GDBM_CLOEXEC);
   326
   327    /* Zero-length file can't be a reader... */
   328    if (((flags & GDBM_OPENMASK) == GDBM_READER) && (file_stat.st_size == 0))
   329      {
   330        if (!(flags & GDBM_CLOERROR))
   331          dbf->desc = -1;
   332        gdbm_close (dbf);
   333        GDBM_SET_ERRNO2 (NULL, GDBM_EMPTY_DATABASE, FALSE, GDBM_DEBUG_OPEN);
   334        return NULL;
   335      }
   336
   337    /* Record the kind of user. */
   338    dbf->read_write = (flags & GDBM_OPENMASK);
   339
   340    /* Lock the file in the appropriate way. */
   341    if (dbf->file_locking)
   342      {
   343        if (_gdbm_lock_file (dbf) == -1)
   344          {
   345            if (!(flags & GDBM_CLOERROR))
   346              dbf->desc = -1;
   347            SAVE_ERRNO (gdbm_close (dbf));
   348            GDBM_SET_ERRNO2 (NULL,
   349                             (flags & GDBM_OPENMASK) == GDBM_READER
   350                               ? GDBM_CANT_BE_READER : GDBM_CANT_BE_WRITER,
   351                             FALSE,
   352                             GDBM_DEBUG_OPEN);
   353            return NULL;
   354          }
   355      }
   356
   357    /* If we do have a write lock and it was a GDBM_NEWDB, it is
   358       now time to truncate the file. */
   359    if ((flags & GDBM_OPENMASK) == GDBM_NEWDB && file_stat.st_size != 0)
   360      {
   361        if (_gdbm_ftruncate (dbf))
   362          {
   363            GDBM_SET_ERRNO2 (dbf, GDBM_FILE_TRUNCATE_ERROR, FALSE,
   364                             GDBM_DEBUG_OPEN);
   365          }
   366        else if (fstat (dbf->desc, &file_stat))
   367          {
   368            GDBM_SET_ERRNO2 (dbf, GDBM_FILE_STAT_ERROR, FALSE, GDBM_DEBUG_OPEN);
   369          }
   370
   371        if (gdbm_last_errno (dbf))
   372          {
   373            if (!(flags & GDBM_CLOERROR))
   374              dbf->desc = -1;
   375            SAVE_ERRNO (gdbm_close (dbf));
   376            return NULL;
   377          }
   378      }
   379
   380    /* Decide if this is a new file or an old file. */
   381    if (file_stat.st_size == 0)
   382      {
   383        /* This is a new file.  Create an empty database.  */
   384        int dir_size, dir_bits;
   385
   386        /* Start with the blocksize. */
   387        if (block_size < GDBM_MIN_BLOCK_SIZE)
   388          {
   389            block_size = STATBLKSIZE (file_stat);
   390            flags &= ~GDBM_BSEXACT;
   391          }
   392        compute_directory_size (block_size, &dir_size, &dir_bits);
   393        GDBM_DEBUG (GDBM_DEBUG_OPEN, "%s: computed dir_size=%d, dir_bits=%d",
   394                    dbf->name, dir_size, dir_bits);
   395        /* Check for correct block_size. */
   396        if (dir_size != block_size)
   397          {
   398            if (flags & GDBM_BSEXACT)
   399              {
   400                if (!(flags & GDBM_CLOERROR))
   401                  dbf->desc = -1;
   402                gdbm_close (dbf);
   403                GDBM_SET_ERRNO2 (NULL, GDBM_BLOCK_SIZE_ERROR, FALSE,
   404                                 GDBM_DEBUG_OPEN);
   405                return NULL;
   406              }
   407            else
   408              block_size = dir_size;
   409          }
   410        GDBM_DEBUG (GDBM_DEBUG_OPEN, "%s: block_size=%d", dbf->name, block_size);
   411
   412        /* Get space for the file header. It will be written to disk, so
   413           make sure there's no garbage in it. */
   414        dbf->header = calloc (1, block_size);
   415        if (dbf->header == NULL)
   416          {
   417            if (!(flags & GDBM_CLOERROR))
   418              dbf->desc = -1;
   419            gdbm_close (dbf);
   420            GDBM_SET_ERRNO2 (NULL, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_OPEN);
   421            return NULL;
   422          }
   423
   424        /* Set the magic number and the block_size. */
   425        if (flags & GDBM_NUMSYNC)
   426          dbf->header->header_magic = GDBM_NUMSYNC_MAGIC;
   427        else
   428          dbf->header->header_magic = GDBM_MAGIC;
   429
   430        /*
   431         * Set block size.  It must be initialized for gdbm_header_avail to work.
   432         */
   433        dbf->header->block_size = block_size;
   434        gdbm_header_avail (dbf->header, &dbf->avail, &dbf->avail_size, &dbf->xheader);
   435        dbf->header->dir_size = dir_size;
   436        dbf->header->dir_bits = dir_bits;
   437
   438        /* Allocate the space for the directory. */
   439        dbf->dir = (off_t *) malloc (dbf->header->dir_size);
   440        if (dbf->dir == NULL)
   441          {
   442            if (!(flags & GDBM_CLOERROR))
   443              dbf->desc = -1;
   444            gdbm_close (dbf);
   445            GDBM_SET_ERRNO2 (NULL, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_OPEN);
   446            return NULL;
   447          }
   448        dbf->header->dir = dbf->header->block_size;
   449
   450        /* Create the first and only hash bucket. */
   451        dbf->header->bucket_elems = bucket_element_count (dbf->header->block_size);
   452        dbf->header->bucket_size  = dbf->header->block_size;
   453        dbf->bucket = calloc (1, dbf->header->bucket_size);
   454        if (dbf->bucket == NULL)
   455          {
   456            if (!(flags & GDBM_CLOERROR))
   457              dbf->desc = -1;
   458            gdbm_close (dbf);
   459            GDBM_SET_ERRNO2 (NULL, GDBM_MALLOC_ERROR, FALSE, GDBM_DEBUG_OPEN);
   460            return NULL;
   461          }
   462        _gdbm_new_bucket (dbf, dbf->bucket, 0);
   463        dbf->bucket->av_count = 1;
   464        dbf->bucket->bucket_avail[0].av_adr = 3*dbf->header->block_size;
   465        dbf->bucket->bucket_avail[0].av_size = dbf->header->block_size;
   466
   467        /* Set table entries to point to hash buckets. */
   468        for (index = 0; index < GDBM_DIR_COUNT (dbf); index++)
   469          dbf->dir[index] = 2*dbf->header->block_size;
   470
   471        /* Initialize the active avail block. */
   472        dbf->avail->size = (dbf->avail_size - offsetof(avail_block, av_table))
   473                            / sizeof (avail_elem);
   474        dbf->avail->count = 0;
   475        dbf->avail->next_block = 0;
   476
   477        dbf->header->next_block  = 4*dbf->header->block_size;
   478
   479        /* Write initial configuration to the file. */
   480        /* Block 0 is the file header and active avail block. */
   481        if (_gdbm_full_write (dbf, dbf->header, dbf->header->block_size))
   482          {
   483            GDBM_DEBUG (GDBM_DEBUG_OPEN|GDBM_DEBUG_ERR,
   484                        "%s: error writing header: %s",
   485                        dbf->name, gdbm_db_strerror (dbf));
   486            if (!(flags & GDBM_CLOERROR))
   487              dbf->desc = -1;
   488            SAVE_ERRNO (gdbm_close (dbf));
   489            return NULL;
   490          }
   491
   492        /* Block 1 is the initial bucket directory. */
   493        if (_gdbm_full_write (dbf, dbf->dir, dbf->header->dir_size))
   494          {
   495            GDBM_DEBUG (GDBM_DEBUG_OPEN|GDBM_DEBUG_ERR,
   496                        "%s: error writing directory: %s",
   497                        dbf->name, gdbm_db_strerror (dbf));
   498            if (!(flags & GDBM_CLOERROR))
   499              dbf->desc = -1;
   500            SAVE_ERRNO (gdbm_close (dbf));
   501            return NULL;
   502          }
   503
   504        /* Block 2 is the only bucket. */
   505        if (_gdbm_full_write (dbf, dbf->bucket, dbf->header->bucket_size))
   506          {
   507            GDBM_DEBUG (GDBM_DEBUG_OPEN|GDBM_DEBUG_ERR,
   508                        "%s: error writing bucket: %s",
   509                        dbf->name, gdbm_db_strerror (dbf));
   510            if (!(flags & GDBM_CLOERROR))
   511              dbf->desc = -1;
   512            SAVE_ERRNO (gdbm_close (dbf));
   513            return NULL;
   514          }
   515
   516        if (_gdbm_file_extend (dbf, dbf->header->next_block))
   517          {
   518            GDBM_DEBUG (GDBM_DEBUG_OPEN|GDBM_DEBUG_ERR,
   519                        "%s: error extending file: %s",
   520                        dbf->name, gdbm_db_strerror (dbf));
   521            if (!(flags & GDBM_CLOERROR))
   522              dbf->desc = -1;
   523            SAVE_ERRNO (gdbm_close (dbf));
   524            return NULL;
   525          }
   526
   527        /* Wait for initial configuration to be written to disk. */
   528        gdbm_file_sync (dbf);
   529
   530        free (dbf->bucket);
   531      }
   532    else
   533      {
   534        /* This is an old database.  Read in the information from the file
   535           header and initialize the hash directory. */
   536
   537        gdbm_file_header partial_header;  /* For the first part of it. */
   538        int rc;
   539
   540        /* Read the partial file header. */
   541        if (_gdbm_full_read (dbf, &partial_header, sizeof (partial_header)))
   542          {
