   153  /* Frees element ELEM.  Unlinks it from the cache tree and LRU list. */
   154  static void
   155  cache_elem_free (GDBM_FILE dbf, cache_elem *elem)
   156  {
   157    _gdbm_cache_tree_delete (dbf->cache_tree, elem->ca_node);
   158    lru_unlink_elem (dbf, elem);
   159    elem->ca_next = dbf->cache_avail;
   160    dbf->cache_avail = elem;
   161    dbf->cache_num--;
   162  }
   163
   164  /* Free the least recently used cache entry. */
   165  static inline int
   166  cache_lru_free (GDBM_FILE dbf)
   167  {
   168    cache_elem *last = dbf->cache_lru;
   169    if (last->ca_changed)
   170      {
   171        if (_gdbm_write_bucket (dbf, last))
   172          return -1;
   173      }
   174    cache_elem_free (dbf, last);
   175    return 0;
   176  }
   177
   178  static int
   179  cache_lookup (GDBM_FILE dbf, off_t adr, cache_elem *ref, cache_elem **ret_elem)
   180  {
   181    int rc;
   182    cache_node *node;
   183    cache_elem *elem;
   184    int retrying = 0;
   185
   186    dbf->cache_access_count++;
   187   retry:
   188    rc = _gdbm_cache_tree_lookup (dbf->cache_tree, adr, &node);
   189    switch (rc)
   190      {
   191      case node_found:
   192        elem = node->elem;
   193        elem->ca_hits++;
   194        dbf->cache_hits++;
   195        lru_unlink_elem (dbf, elem);
   196        break;
   197
   198      case node_new:
   199        elem = cache_elem_new (dbf, adr);
   200        if (!elem)
   201          {
   202            _gdbm_cache_tree_delete (dbf->cache_tree, node);
   203            return node_failure;
   204          }
   205        elem->ca_node = node;
   206        node->elem = elem;
   207
   208        if (dbf->cache_size != GDBM_CACHE_AUTO
   209            && dbf->cache_num > dbf->cache_size
   210            && cache_lru_free (dbf))
   211          {
   212            cache_elem_free (dbf, elem);
   213            return node_failure;
   214          }
   215        break;
   216
   217      case node_failure:
   218        if (!retrying)
   219          {
   220            if (errno == ENOMEM)
   221              {
   222                /* Release the last recently used element and retry. */
   223                if (cache_lru_free (dbf))
   224                  return node_failure;
   225                retrying = 1;
   226                goto retry;
   227              }
   228          }
   229        return node_failure;
   230
   231      default:
   232        abort ();
   233      }
   234
   235    lru_link_elem (dbf, elem, ref);
   236    *ret_elem = elem;
   237    return rc;
   238  }
