   256    if (!gdbm_dir_entry_valid_p (dbf, dir_index))
   257      {
   258        /* FIXME: negative caching? */
   259        GDBM_SET_ERRNO (dbf, GDBM_BAD_DIR_ENTRY, TRUE);
   260        return -1;
   261      }
   262
   263    /* Initial set up. */
   264    dbf->bucket_dir = dir_index;
   265    bucket_adr = dbf->dir[dir_index];
   266
   267    if (dbf->cache_entry && dbf->cache_entry->ca_adr == bucket_adr)
   268      return 0;
   269
   270    switch (cache_lookup (dbf, bucket_adr, NULL, &elem))
   271      {
   272      case node_found:
   273        break;
   274
   275      case node_new:
   276        /* Position the file pointer */
   277        file_pos = gdbm_file_seek (dbf, bucket_adr, SEEK_SET);
   278        if (file_pos != bucket_adr)
   279          {
   280            GDBM_SET_ERRNO (dbf, GDBM_FILE_SEEK_ERROR, TRUE);
   281            cache_elem_free (dbf, elem);
   282            _gdbm_fatal (dbf, _("lseek error"));
   283            return -1;
   284          }
   285
   286        /* Read the bucket. */
   287        rc = _gdbm_full_read (dbf, elem->ca_bucket, dbf->header->bucket_size);
   288        if (rc)
   289          {
   290            GDBM_DEBUG (GDBM_DEBUG_ERR,
   291                        "%s: error reading bucket: %s",
   292                        dbf->name, gdbm_db_strerror (dbf));
   293            dbf->need_recovery = TRUE;
   294            cache_elem_free (dbf, elem);
   295            _gdbm_fatal (dbf, gdbm_db_strerror (dbf));
   296            return -1;
   297          }
   298
   299        /* Validate the bucket */
   300        bucket = elem->ca_bucket;
   301        if (!(bucket->count >= 0
   302              && bucket->count <= dbf->header->bucket_elems
   303              && bucket->bucket_bits >= 0
   304              && bucket->bucket_bits <= dbf->header->dir_bits))
   305          {
   306            GDBM_SET_ERRNO (dbf, GDBM_BAD_BUCKET, TRUE);
   307            cache_elem_free (dbf, elem);
