    20  /* Read exactly SIZE bytes of data into BUFFER.  Return value is 0 on
    21     success, and -1 on error.  In the latter case, gdbm_errno is set to
    22     GDBM_FILE_EOF, if not enough data is available, and to
    23     GDBM_FILE_READ_ERROR, if a read error occurs. */
    24  int
    25  _gdbm_full_read (GDBM_FILE dbf, void *buffer, size_t size)
    26  {
    27    char *ptr = buffer;
    28    while (size)
    29      {
    30        ssize_t rdbytes = gdbm_file_read (dbf, ptr, size);
    31        if (rdbytes == -1)
    32          {
    33            if (errno == EINTR)
    34              continue;
    35            if (gdbm_last_errno (dbf) == GDBM_NO_ERROR)
    36              GDBM_SET_ERRNO (dbf, GDBM_FILE_READ_ERROR, FALSE);
    37            return -1;
    38          }
    39        if (rdbytes == 0)
    40          {
    41            GDBM_SET_ERRNO (dbf, GDBM_FILE_EOF, FALSE);
    42            return -1;
    43          }
    44        ptr += rdbytes;
    45        size -= rdbytes;
    46      }
    47    return 0;
    48  }
    49
    50  /* Write exactly SIZE bytes of data from BUFFER tp DBF.  Return 0 on
    51     success, and -1 (setting gdbm_errno to GDBM_FILE_READ_ERROR) on error. */
    52  int
    53  _gdbm_full_write (GDBM_FILE dbf, void *buffer, size_t size)
    54  {
    55    char *ptr = buffer;
    56
    57    /* Invalidate file_size */
    58    dbf->file_size = -1;
    59    while (size)
    60      {
    61        ssize_t wrbytes = gdbm_file_write (dbf, ptr, size);
    62        if (wrbytes == -1)
    63          {
    64            if (errno == EINTR)
    65              continue;
    66            if (gdbm_last_errno (dbf) == GDBM_NO_ERROR)
    67              GDBM_SET_ERRNO (dbf, GDBM_FILE_WRITE_ERROR, TRUE);
    68            return -1;
    69          }
    70        if (wrbytes == 0)
    71          {
    72            errno = ENOSPC;
    73            GDBM_SET_ERRNO (dbf, GDBM_FILE_WRITE_ERROR, TRUE);
    74            return -1;
    75          }
    76        ptr += wrbytes;
    77        size -= wrbytes;
    78      }
    79    return 0;
    80  }
