    78  /* Remap the DBF file according to dbf->{mapped_off,mapped_pos,mapped_size}.
    79     Take care to recompute {mapped_off,mapped_pos} so that the former lies
    80     on a page size boundary. */
    81  int
    82  _gdbm_internal_remap (GDBM_FILE dbf, size_t size)
    83  {
    84    void *p;
    85    int flags = MAP_SHARED;
    86    int prot = PROT_READ;
    87    size_t page_size = sysconf (_SC_PAGESIZE);
    88
    89    if (dbf->mapped_region)
    90      {
    91        munmap (dbf->mapped_region, dbf->mapped_size);
    92        dbf->mapped_region = NULL;
    93      }
    94    dbf->mapped_size = size;
    95
    96    if (size == 0)
    97      return 0;
    98
    99    dbf->mapped_pos += dbf->mapped_off % page_size;
   100    dbf->mapped_off = (dbf->mapped_off / page_size) * page_size;
   101
   102    if (dbf->read_write)
   103      prot |= PROT_WRITE;
   104
   105    if (dbf->mmap_preread)
   106      {
   107        flags |= GDBM_MMAP_PREREAD;
   108      }
   109
   110    p = mmap (NULL, dbf->mapped_size, prot, flags, dbf->desc, dbf->mapped_off);
   111    if (p == MAP_FAILED)
   112      {
   113        dbf->mapped_region = NULL;
   114        GDBM_SET_ERRNO (dbf, GDBM_MALLOC_ERROR, FALSE);
   115        return -1;
   116      }
   117
   118    dbf->mapped_region = p;
   119    return 0;
   120  }
