   159      {
   160        SAVE_ERRNO (_gdbm_mapped_unmap (dbf));
   161        return -1;
   162      }
   163
   164    if (flag == _REMAP_END && size < file_size)
   165      size = file_size;
   166
   167    if (dbf->read_write)
   168      {
   169        if (size > file_size)
   170          {
   171            if (flag != _REMAP_DEFAULT)
   172              {
   173                if (size < dbf->header->next_block)
   174                  size = dbf->header->next_block;
   175                if (_gdbm_file_extend (dbf, size))
   176                  return -1;
   177                file_size = size;
